const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define San Juan, Puerto Rico location
  const sanJuan = ee.Geometry.Point([-66.1057, 18.4655]);
  const region = sanJuan.buffer(10000); // 10km buffer around city center

  // Define date ranges
  const date1Start = '2017-09-01';
  const date1End = '2017-09-03';
  const date2Start = '2017-09-27';
  const date2End = '2017-09-29';

  try {
    // Try VIIRS DNB Monthly product first
    let col1 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
      .filterBounds(region)
      .filterDate('2017-09-01', '2017-09-02');

    let col2 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
      .filterBounds(region)
      .filterDate('2017-09-01', '2017-10-01');

    const size1 = await col1.size().getInfo();
    const size2 = await col2.size().getInfo();

    console.log(`Monthly collection Sept 1: ${size1} images`);
    console.log(`Monthly collection Sept (full): ${size2} images`);

    // Monthly data likely won't have daily resolution, use composite for the month
    if (size2 === 0) {
      console.log("No VIIRS monthly data available");
      console.log("<answer>C1</answer>");
      return;
    }

    // Get September 2017 composite and sample at two dates
    const sept2017 = col2.first().select('avg_rad');

    // Calculate mean brightness for early September (using monthly composite)
    const stats1 = await sept2017.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    // For post-hurricane, we need to check if there's significant change
    // Since monthly data aggregates the whole month, let's use a different approach
    // Check MOD13A2 or use annual comparison

    // Actually, let's use VIIRS annual composites or check the monthly value
    const earlyCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
      .filterBounds(region)
      .filterDate('2017-08-01', '2017-09-20'); // Pre-hurricane

    const lateCol = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
      .filterBounds(region)
      .filterDate('2017-09-20', '2017-10-15'); // Post-hurricane

    const earlySize = await earlyCol.size().getInfo();
    const lateSize = await lateCol.size().getInfo();

    console.log(`Pre-hurricane images: ${earlySize}`);
    console.log(`Post-hurricane images: ${lateSize}`);

    if (earlySize === 0 || lateSize === 0) {
      console.log("Insufficient temporal coverage");
      console.log("<answer>C1</answer>");
      return;
    }

    const earlyImg = earlyCol.mean().select('avg_rad');
    const lateImg = lateCol.mean().select('avg_rad');

    const earlyStats = await earlyImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const lateStats = await lateImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const earlyBrightness = earlyStats.avg_rad;
    const lateBrightness = lateStats.avg_rad;

    console.log(`Early Sept brightness: ${earlyBrightness !== null ? earlyBrightness.toFixed(2) : 'null'}`);
    console.log(`Late Sept brightness: ${lateBrightness !== null ? lateBrightness.toFixed(2) : 'null'}`);

    if (earlyBrightness === null || lateBrightness === null || 
        isNaN(earlyBrightness) || isNaN(lateBrightness)) {
      console.log("Invalid brightness values");
      console.log("<answer>C3</answer>");
      return;
    }

    if (lateBrightness < earlyBrightness) {
      console.log(`Brightness decreased: ${lateBrightness.toFixed(2)} < ${earlyBrightness.toFixed(2)}`);
      console.log("<answer>A</answer>");
    } else {
      console.log(`Brightness not lower: ${lateBrightness.toFixed(2)} >= ${earlyBrightness.toFixed(2)}`);
      console.log("<answer>B</answer>");
    }

  } catch (error) {
    console.log(`Error: ${error.message}`);
    console.log("<answer>D</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
